<?php
require_once __DIR__.'/equipment-navigation.php';
function atm_farmet_data(): array { static $data; return $data??=json_decode(file_get_contents(__DIR__.'/farmet-data.json'),true,512,JSON_THROW_ON_ERROR); }
function atm_farmet_model(): ?array {
    $id=$_GET['model']??'SOFTER-6PS';if(!is_string($id))return null;
    foreach(atm_farmet_data()['models'] as $model)if($model['id']===strtoupper($id))return $model;
    return null;
}
function atm_farmet_power(array $model): string {
    $power=$model['power'];return !$power?'Уточнить':($power[1]===null?'от '.$power[0]:($power[0]===$power[1]?$power[0]:$power[0].'–'.$power[1])).' л.с.';
}
function atm_farmet_width(array $model): string { return $model['width']!==null?str_replace('.',',',(string)$model['width']).' м':'Уточнить'; }
function atm_farmet_whatsapp(?array $model=null,string $purpose='цена, наличие и комплектация'): string {
    return 'https://wa.me/77775550665?text='.rawurlencode('Здравствуйте! Интересует '.($model['name']??'техника Farmet').'. Подскажите: '.$purpose.'.');
}
function atm_farmet_card(array $model,bool $compare=false,bool $compact=false): void {
    $url=atm_yto_url('/farmet-product/?model='.$model['id']);
    $types=['disc'=>'Дисковый лущильник','tine'=>'Культиватор / глубокорыхлитель','drill'=>'Посевная техника','roller'=>'Катки']; ?>
<article class="product catalog-product sampo-card farmet-card" data-id="<?= $model['id'] ?>" data-name="<?= atm_yto_escape($model['name']) ?>" data-kind="<?= $model['kind'] ?>" data-width="<?= $model['width']??0 ?>" data-demo="<?= $model['demo']?'true':'false' ?>"><a class="product-photo" href="<?= atm_yto_escape($url) ?>"><img src="<?= atm_yto_escape(atm_yto_asset($model['image'])) ?>" alt="<?= atm_yto_escape($model['name']) ?> — место для фотографии" loading="lazy"><?php if($model['demo']): ?><span class="stock-badge farmet-demo-badge">Демо · уточнить состояние</span><?php endif ?></a><div class="product-body"><span class="sampo-card-type"><?= $types[$model['kind']] ?></span><h3><a href="<?= atm_yto_escape($url) ?>"><?= atm_yto_escape($model['name']) ?></a></h3><?php if(!$compact): ?><p class="product-caption"><?= atm_yto_escape($model['lead']) ?></p><?php endif ?><div class="farmet-card-specs"><span><b>Рабочая ширина</b><?= atm_yto_escape(atm_farmet_width($model)) ?></span><span><b>Глубина</b><?= atm_yto_escape($model['depth']??'Уточнить') ?></span><span><b>Мощность трактора</b><?= atm_yto_escape(atm_farmet_power($model)) ?></span></div><div class="product-actions"><a class="button small" href="<?= atm_yto_escape($url) ?>">Подробнее →</a><a class="button outline small" href="<?= atm_yto_escape(atm_farmet_whatsapp($model)) ?>" target="_blank" rel="noopener">Получить КП</a></div><?php if($compare): ?><label class="compare-choice"><input type="checkbox" data-farmet-compare="<?= $model['id'] ?>"> Сравнить модель</label><?php endif ?></div></article>
<?php }
